<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Search } from '@element-plus/icons-vue'
import { api, useRequestError } from '../api'
import PageHeading from '../components/PageHeading.vue'
const route=useRoute();const onError=useRequestError();const rows=ref([]);const query=ref('');const lowOnly=ref(route.query.low_stock==='1');const loading=ref(false);const dialog=ref(false);const saving=ref(false);const selected=ref(null);const form=ref({quantity:0,note:''})
const lowCount=computed(()=>rows.value.filter((item)=>item.stock<=item.reorder_level).length)
async function load(){loading.value=true;try{const params=new URLSearchParams({page_size:'100'});if(query.value)params.set('q',query.value);if(lowOnly.value)params.set('low_stock','true');rows.value=(await api.inventory(`?${params}`)).items}catch(e){onError(e)}finally{loading.value=false}}
function open(row){selected.value=row;form.value={quantity:0,note:''};dialog.value=true}
async function submit(){if(!form.value.quantity){ElMessage.warning('调整数量不能为 0');return}saving.value=true;try{await api.adjustInventory({product_id:selected.value.id,quantity:Number(form.value.quantity),note:form.value.note});ElMessage.success('库存已调整');dialog.value=false;await load()}catch(e){onError(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><PageHeading title="库存管理" subtitle="查看库存水平、处理预警和盘点调整"><template #default><el-button type="primary" @click="$router.push({name:'purchases'})"><el-icon><CirclePlus/></el-icon>采购入库</el-button></template></PageHeading><section class="surface module-surface"><div class="inventory-summary"><div><span>商品总数</span><strong>{{ rows.length }}</strong></div><div><span>库存预警</span><strong class="stock-low">{{ lowCount }}</strong></div><div class="inventory-filter"><el-input v-model="query" placeholder="搜索商品名称或编码" :prefix-icon="Search" clearable @keyup.enter="load"/><el-checkbox v-model="lowOnly" @change="load">仅看预警</el-checkbox></div></div><div class="table-scroll"><el-table :data="rows" v-loading="loading" stripe style="width:100%" empty-text="暂无库存记录"><el-table-column prop="sku" label="商品编码" min-width="130"/><el-table-column prop="name" label="商品名称" min-width="220"/><el-table-column prop="category" label="分类" min-width="130"/><el-table-column prop="unit" label="单位" width="80"/><el-table-column label="可用库存" min-width="180"><template #default="s"><div class="stock-cell"><strong :class="{'stock-low':s.row.stock<=s.row.reorder_level}">{{ s.row.stock }} {{ s.row.unit }}</strong><el-progress :percentage="Math.min(100,Math.round(s.row.stock/Math.max(1,s.row.reorder_level*2)*100))" :show-text="false" :status="s.row.stock<=s.row.reorder_level?'exception':'success'"/></div></template></el-table-column><el-table-column label="安全库存" width="110"><template #default="s">{{ s.row.reorder_level }} {{ s.row.unit }}</template></el-table-column><el-table-column label="状态" width="120"><template #default="s"><el-tag :type="s.row.stock<=s.row.reorder_level?'danger':'success'" effect="light">{{ s.row.stock<=s.row.reorder_level?'库存预警':'库存正常' }}</el-tag></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">调整</el-button></template></el-table-column></el-table></div></section><el-dialog v-model="dialog" title="库存调整" width="460px"><p class="dialog-product">{{ selected?.name }} <span>{{ selected?.sku }}</span></p><el-form label-position="top"><el-form-item label="调整数量（正数入库，负数出库）"><el-input-number v-model="form.quantity" :step="1" controls-position="right"/></el-form-item><el-form-item label="调整说明"><el-input v-model="form.note" placeholder="如：盘点修正"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">确认调整</el-button></template></el-dialog></div></template>
